#' ctDNA / MRD Dynamics
#'
#' Analyses circulating-tumour-DNA (ctDNA) / minimal-residual-disease (MRD) 
#' kinetics from paired baseline and follow-up variant allele fractions (VAF): 
#' clearance vs persistence classification, log-fold change, and MRD status as 
#' a predictor of survival by a landmark analysis.
#' 
#' @param data .
#' @param baselineVaf Variant allele fraction (or ctDNA concentration) at
#'   baseline / pre-treatment.
#' @param followupVaf Variant allele fraction (or ctDNA concentration) at the
#'   follow-up / MRD timepoint.
#' @param detectionThreshold VAF at or below which the follow-up sample is
#'   classed as cleared / MRD-negative.
#' @param timeBetween Time between the baseline and follow-up draws, used to
#'   report a clearance rate (change in log VAF per unit time).
#' @param group Optional grouping variable (e.g. treatment arm) for stratified
#'   clearance rates.
#' @param survivalTime .
#' @param survivalStatus .
#' @param eventLevel .
#' @param conf_level .
#' @param showClassification .
#' @param showDynamics .
#' @param showSurvival .
#' @param showPlot .
#' @param showSummary .
#' @param showExplanation .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$todo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$classificationTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$dynamicsTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$survivalTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$addStatusToData} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$explanation} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$classificationTable$asDF}
#'
#' \code{as.data.frame(results$classificationTable)}
#'
#' @export
ctdnadynamics <- function(
    data,
    baselineVaf,
    followupVaf,
    detectionThreshold = 0.05,
    timeBetween,
    group,
    survivalTime,
    survivalStatus,
    eventLevel,
    conf_level = 0.95,
    showClassification = TRUE,
    showDynamics = TRUE,
    showSurvival = TRUE,
    showPlot = TRUE,
    showSummary = TRUE,
    showExplanation = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("ctdnadynamics requires jmvcore to be installed (restart may be required)")

    if ( ! missing(baselineVaf)) baselineVaf <- jmvcore::resolveQuo(jmvcore::enquo(baselineVaf))
    if ( ! missing(followupVaf)) followupVaf <- jmvcore::resolveQuo(jmvcore::enquo(followupVaf))
    if ( ! missing(timeBetween)) timeBetween <- jmvcore::resolveQuo(jmvcore::enquo(timeBetween))
    if ( ! missing(group)) group <- jmvcore::resolveQuo(jmvcore::enquo(group))
    if ( ! missing(survivalTime)) survivalTime <- jmvcore::resolveQuo(jmvcore::enquo(survivalTime))
    if ( ! missing(survivalStatus)) survivalStatus <- jmvcore::resolveQuo(jmvcore::enquo(survivalStatus))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(baselineVaf), baselineVaf, NULL),
            `if`( ! missing(followupVaf), followupVaf, NULL),
            `if`( ! missing(timeBetween), timeBetween, NULL),
            `if`( ! missing(group), group, NULL),
            `if`( ! missing(survivalTime), survivalTime, NULL),
            `if`( ! missing(survivalStatus), survivalStatus, NULL))

    for (v in group) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- ctdnadynamicsOptions$new(
        baselineVaf = baselineVaf,
        followupVaf = followupVaf,
        detectionThreshold = detectionThreshold,
        timeBetween = timeBetween,
        group = group,
        survivalTime = survivalTime,
        survivalStatus = survivalStatus,
        eventLevel = eventLevel,
        conf_level = conf_level,
        showClassification = showClassification,
        showDynamics = showDynamics,
        showSurvival = showSurvival,
        showPlot = showPlot,
        showSummary = showSummary,
        showExplanation = showExplanation)

    analysis <- ctdnadynamicsClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

